"use client"

import { useState, useRef, useEffect, memo } from "react"

// --- Types ---

type ComponentMeta = {
  name: string
  slug: string
  exportName: string
  loader: () => Promise<Record<string, any>>
}

type Section = {
  category: string
  items: ComponentMeta[]
}

// --- Lazy Preview (loads component when scrolled into view) ---

const LazyPreview = memo(function LazyPreview({
  loader,
  exportName,
}: {
  loader: () => Promise<Record<string, any>>
  exportName: string
}) {
  const ref = useRef<HTMLDivElement>(null)
  const [Component, setComponent] = useState<React.ComponentType | null>(null)
  const [error, setError] = useState(false)

  useEffect(() => {
    const el = ref.current
    if (!el) return
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          observer.disconnect()
          loader()
            .then((mod) => {
              const Comp = mod[exportName] || mod.default
              if (Comp) setComponent(() => Comp)
              else setError(true)
            })
            .catch(() => setError(true))
        }
      },
      { rootMargin: "400px" }
    )
    observer.observe(el)
    return () => observer.disconnect()
  }, [loader, exportName])

  if (error) {
    return (
      <div ref={ref} className="flex items-center justify-center py-12 text-sm text-muted-foreground">
        Failed to load component
      </div>
    )
  }

  return (
    <div ref={ref}>
      {Component ? (
        <Component />
      ) : (
        <div className="flex items-center justify-center py-16 text-muted-foreground">
          <div className="h-6 w-6 animate-spin rounded-full border-2 border-muted-foreground border-t-transparent" />
        </div>
      )}
    </div>
  )
})

