// --- Page ---

export default function RelumeLibraryPage() {
  const [filter, setFilter] = useState<string | null>(null)
  const [search, setSearch] = useState("")

  const filtered = sections
    .filter((s) => !filter || s.category === filter)
    .map((s) => {
      if (!search) return s
      const q = search.toLowerCase()
      const matchedItems = s.items.filter(
        (c) => c.name.toLowerCase().includes(q) || c.slug.toLowerCase().includes(q)
      )
      return matchedItems.length > 0 ? { ...s, items: matchedItems } : null
    })
    .filter(Boolean) as Section[]

  const totalShown = filtered.reduce((n, s) => n + s.items.length, 0)

  return (
    <div className="min-h-screen bg-background">
      <div className="mx-auto max-w-7xl px-4 py-12 sm:px-6 lg:px-8">
        <div className="mb-6">
          <h1 className="text-4xl font-bold tracking-tight">Relume Library</h1>
          <p className="mt-2 text-lg text-muted-foreground">
            Official Relume React components imported directly from the library.{" "}
            <span className="font-medium text-foreground">
              {sections.reduce((n, s) => n + s.items.length, 0)} components
            </span>{" "}
            across {sections.length} categories.
          </p>
        </div>

        <div className="sticky top-0 z-40 -mx-4 bg-background/95 px-4 py-4 backdrop-blur supports-[backdrop-filter]:bg-background/80 sm:-mx-6 sm:px-6 lg:-mx-8 lg:px-8">
          <input
            type="text"
            placeholder="Search components..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="mb-3 w-full rounded-lg border border-border bg-background px-4 py-2 text-sm placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-ring"
          />
          <div className="flex flex-wrap gap-2">
            <button
              onClick={() => setFilter(null)}
              className={`rounded-full px-3 py-1 text-sm font-medium transition-colors ${
                filter === null
                  ? "bg-foreground text-background"
                  : "bg-muted text-muted-foreground hover:bg-muted/80"
              }`}
            >
              All ({sections.reduce((n, s) => n + s.items.length, 0)})
            </button>
            {sections.map((s) => (
              <button
                key={s.category}
                onClick={() => setFilter(filter === s.category ? null : s.category)}
                className={`rounded-full px-3 py-1 text-sm font-medium transition-colors ${
                  filter === s.category
                    ? "bg-foreground text-background"
                    : "bg-muted text-muted-foreground hover:bg-muted/80"
                }`}
              >
                {s.category} ({s.items.length})
              </button>
            ))}
          </div>
          {(filter || search) && (
            <p className="mt-2 text-sm text-muted-foreground">
              Showing {totalShown} component{totalShown !== 1 ? "s" : ""}
              {filter && (
                <>
                  {" "}in <span className="font-medium text-foreground">{filter}</span>
                </>
              )}
              {search && (
                <>
                  {" "}matching{" "}
                  <span className="font-medium text-foreground">&ldquo;{search}&rdquo;</span>
                </>
              )}
            </p>
          )}
        </div>

        <div className="mt-8">
          {filtered.map((section) => (
            <div key={section.category} className="mb-16">
              <h2 className="text-2xl font-semibold tracking-tight mb-8">
                {section.category}
                <span className="ml-2 text-base font-normal text-muted-foreground">
                  ({section.items.length})
                </span>
              </h2>

              <div className="space-y-16">
                {section.items.map((c) => (
                  <div key={c.slug}>
                    <div className="border-t pt-4">
                      <p className="text-sm font-mono text-muted-foreground mb-2">
                        @/components/relume-library/{c.slug}
                      </p>
                      <h3 className="text-lg font-semibold mb-6">{c.name}</h3>
                    </div>
                    <div className="rounded-xl border border-border overflow-hidden [transform:translateZ(0)]">
                      <LazyPreview loader={c.loader} exportName={c.exportName} />
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))}

          {filtered.length === 0 && (
            <div className="py-24 text-center text-muted-foreground">
              No components found.
            </div>
          )}
        </div>
      </div>
    </div>
  )
}
